"use client";

// Generated by GitHub Copilot - Oct-11-2026
import { useEffect, useState } from "react";
import Link from "next/link";
import { Alert, Box, Button, Container, Stack } from "@mui/material";
import PageHeader from "@/components/common/PageHeader";
import { LIFE_REFERENCE_EDITIONS, type LifeReferenceEdition } from "@/constants/lifeReference";
import { supabase } from "@/lib/supabaseClient";

/**
 * Loads authenticated reference content or an opt-in external audio player.
 * Local scripts cannot access app storage; audio permissions are limited to its frame.
 */
export default function LifeReferencePage({ edition }: { edition: LifeReferenceEdition }) {
  const reference = LIFE_REFERENCE_EDITIONS[edition];
  const isAudio = edition === "audiobook";
  const [audioRequested, setAudioRequested] = useState(false);
  const [document, setDocument] = useState<{ source: string; html: string } | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);
  const documentHtml = document?.source === reference.source ? document.html : null;

  // Generated by GitHub Copilot - Oct-11-2026
  useEffect(() => {
    if (isAudio) {
      return;
    }

    const controller = new AbortController();

    /**
     * Fetches private HTML with a session token that never enters the embedded document.
     */
    async function loadDocument() {
      setDocument(null);
      setLoadError(null);
      try {
        if (!supabase) {
          throw new Error("Supabase is not configured.");
        }
        const { data, error } = await supabase.auth.getSession();
        if (error) {
          throw new Error(error.message);
        }
        if (!data.session) {
          throw new Error("Sign in to read the Life Reference Book.");
        }
        const response = await fetch(reference.source, {
          headers: { Authorization: `Bearer ${data.session.access_token}` },
          cache: "no-store",
          signal: controller.signal,
        });
        const payload: unknown = await response.json();
        if (!response.ok) {
          const message = payload && typeof payload === "object" && "error" in payload && typeof payload.error === "string"
            ? payload.error
            : "Unable to load the Life Reference Book.";
          throw new Error(message);
        }
        if (!payload || typeof payload !== "object" || !("html" in payload) || typeof payload.html !== "string") {
          throw new Error("The reference service returned an invalid document.");
        }
        if (!controller.signal.aborted) {
          setDocument({ source: reference.source, html: payload.html });
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          setLoadError(error instanceof Error ? error.message : "Unable to load the Life Reference Book.");
        }
      }
    }

    void loadDocument();
    return () => controller.abort();
  }, [isAudio, reference.source, attempt]);

  return (
    <Container maxWidth="xl" sx={{ py: 3 }}>
      <Stack spacing={3}>
        <PageHeader title={reference.title} description={reference.description} />
        <Stack component="nav" aria-label="Life reference editions" direction="row" spacing={1} sx={{ flexWrap: "wrap", gap: 1 }}>
          {Object.entries(LIFE_REFERENCE_EDITIONS).map(([key, item]) => (
            <Button
              key={key}
              component={Link}
              href={item.href}
              variant={key === edition ? "contained" : "outlined"}
              aria-current={key === edition ? "page" : undefined}
            >
              {item.title}
            </Button>
          ))}
          {/* Generated by GitHub Copilot - Oct-11-2026 */}
          {isAudio ? (
            <Button component="a" href={reference.source} target="_blank" rel="noopener noreferrer">
              Open in new tab
            </Button>
          ) : null}
        </Stack>
        {isAudio ? (
          <Alert severity="info">
            The audio player is hosted externally. Loading it connects to that service.
            If it cannot load here, use Open in new tab. Start playback using the player controls.
          </Alert>
        ) : null}
        {!isAudio && loadError ? (
          <Alert severity="error" action={<Button color="inherit" onClick={() => setAttempt((value) => value + 1)}>Retry</Button>}>
            {loadError}
          </Alert>
        ) : !isAudio && documentHtml === null ? (
          <Box role="status">Loading your Life Reference Book...</Box>
        ) : isAudio && !audioRequested ? (
          <Button variant="contained" onClick={() => setAudioRequested(true)} sx={{ alignSelf: "flex-start" }}>
            Load audiobook player
          </Button>
        ) : (
          <Box sx={{ width: "100%", height: 780, maxHeight: "85vh", borderRadius: 2, overflow: "hidden", border: "1px solid", borderColor: "divider", boxShadow: 3 }}>
            <Box
              component="iframe"
              src={isAudio ? reference.source : undefined}
              srcDoc={isAudio ? undefined : documentHtml ?? undefined}
              title={isAudio ? "My Life Reference Book - Audio Edition" : reference.title}
              loading="lazy"
              referrerPolicy="no-referrer"
              sandbox={isAudio ? "allow-scripts allow-same-origin" : "allow-scripts"}
              allow={isAudio ? "autoplay; clipboard-write" : undefined}
              sx={{ display: "block", border: 0, width: "100%", height: "100%" }}
            />
          </Box>
        )}
      </Stack>
    </Container>
  );
}
